window.HB_TR["nehemiah"]["ur"]=["1۔ نحمیاہ بیٹے ہخالیہ کے الفاظ۔ اور یہ بیسویں سال کے مہینے چسلیو میں ہوا، جب میں محل شوشان میں تھا،\n2۔ کہ حنانی، میرے بھائیوں میں سے ایک، آیا، وہ اور {کچھ} یہوداہ کے لوگ؛ اور میں نے ان سے ان یہودیوں کے بارے میں پوچھا جو فرار ہو گئے تھے، جو قید سے بچ گئے تھے، اور یروشلم کے بارے میں۔\n3۔ اور انہوں نے مجھ سے کہا، صوبے میں قید کے باقیات شدید اذیت اور ملامت میں ہیں: یروشلم کی دیوار بھی ٹوٹ چکی ہے، اور اس کے دروازے آگ میں جل رہے ہیں۔\n4۔ اور جب میں نے یہ الفاظ سنے، تو میں بیٹھ گیا، رویا، {کچھ دن} کا سوگ منایا، روزہ رکھا اور آسمان کے خدا کے سامنے دعا کی،\n5۔ اور کہا، اے آسمان کے خداوند خدا، عظیم اور خوفناک خدا، جو ان لوگوں کے لیے عہد اور رحمت قائم رکھتا ہے جو اس سے محبت کرتے ہیں اور اس کے احکامات کی پابندی کرتے ہیں، میں تجھ سے التجا کرتا ہوں:\n6۔ اب اپنا کان ہوشیار رہو، اور اپنی آنکھیں کھول دو، تاکہ تم اپنے خادم کی دعا سن سکو، جو میں اب تمہارے سامنے دن رات دعا کر رہا ہوں، بنی اسرائیل کے لیے تمہارے بندوں کے لیے، اور بنی اسرائیل کے گناہوں کا اعتراف کرو، جو ہم نے تمہارے خلاف گناہ کیے ہیں: میں اور میرے والد کے گھرانے دونوں نے گناہ کیا ہے۔\n7۔ ہم نے تمہارے ساتھ بہت بدعنوانی کی ہے، اور نہ احکامات، نہ قوانین اور نہ وہ فیصلے پورے کیے جو تم نے اپنے خادم موسیٰ کو حکم دیے۔\n8۔ یاد رکھو، میں تم سے التجا کرتا ہوں، وہ کلام جو تم نے اپنے بندے موسیٰ کو حکم دیا تھا، کہ اگر تم نے زیادتی کی، تو میں تمہیں قوموں میں بکھیر دوں گا:\n9. لیکن {اگر} تم میرے پاس رجوع کرو، میرے احکامات کی پیروی کرو، اور انہیں پورا کرو؛ اگرچہ تم میں سے کچھ آسمان کے کونے تک نکالے گئے تھے، {پھر بھی} میں انہیں وہاں سے جمع کروں گا، اور انہیں اس جگہ لے جاؤں گا جہاں میں نے اپنا نام رکھا ہے۔\n10۔ اب یہ آپ کے خادم اور آپ کے لوگ ہیں، جنہیں آپ نے اپنی عظیم طاقت اور طاقتور ہاتھ سے نجات دی ہے۔\n11۔ اے خداوند، میں تجھ سے التجا کرتا ہوں، اب اپنا کان اپنے بندے کی دعا اور اپنے بندوں کی دعا پر توجہ دے جو تیرے نام سے ڈرنا چاہتے ہیں: اور خوش ہو، میں دعا کرتا ہوں کہ آج تیرے بندے کو اس شخص کی نظر میں رحمت عطا فرما۔ کیونکہ میں بادشاہ کا جام بردار تھا۔","1۔ اور یہ مہینہ نیسان، آرتاکسرسٹس بادشاہ کے بیسویں سال میں ہوا، {وہ} شراب {تھی} اس کے سامنے تھی: اور میں نے شراب اٹھائی اور بادشاہ کو دے دی۔ اب میں اس کی موجودگی میں {پہلے} اداس نہیں ہوا تھا۔\n2. بادشاہ نے مجھ سے کیوں کہا، تمہارا چہرہ کیوں اداس ہے، جب کہ تم بیمار نہیں ہو؟ یہ {اور کچھ نہیں} سوائے دل کا غم کے۔ پھر میں بہت خوفزدہ ہو گیا،\n3۔ اور بادشاہ سے کہا، بادشاہ ہمیشہ زندہ رہے: میرا چہرہ کیوں اداس نہ ہو، جب شہر، جو میرے آبا و اجداد کی قبروں کی جگہ ہے، ویران ہے، اور اس کے دروازے آگ میں جل رہے ہیں؟\n4۔ پھر بادشاہ نے مجھ سے کہا، تم کس لیے درخواست کر رہے ہو؟ تو میں نے آسمان کے خدا سے دعا کی۔\n5۔ اور میں نے بادشاہ سے کہا، اگر بادشاہ چاہے، اور اگر تمہارا خادم تمہاری نظر میں خوش ہو گیا ہے، تو تم مجھے یہوداہ بھیجو، میرے آباؤ اجداد کے قبروں کے شہر میں، تاکہ میں اسے تعمیر کر سکوں۔\n6۔ اور بادشاہ نے مجھ سے کہا، (ملکہ بھی اس کے ساتھ بیٹھی تھی،) تمہارا سفر کب تک رہے گا؟ اور تم کب واپس آؤ گے؟ لہٰذا بادشاہ نے مجھے بھیجنے کا فیصلہ کیا؛ اور میں نے اسے وقت مقرر کیا۔ {ملکہ: عبرانی۔ بیوی}\n7۔ مزید میں نے بادشاہ سے کہا، اگر بادشاہ چاہے تو مجھے دریا کے پار حکمرانوں کو خطوط دیے جائیں تاکہ وہ مجھے یہوداہ تک پہنچا دیں؛\n8۔ اور بادشاہ کے جنگل کے محافظ آصف کو ایک خط بھیجا، تاکہ وہ مجھے محل کے دروازوں کے لیے لکڑی دے جو گھر سے منسلک تھے، اور شہر کی دیوار کے لیے، اور اس گھر کے لیے جس میں میں داخل ہونا تھا۔ اور بادشاہ نے مجھے عطا کیا، میرے خدا کے اچھے ہاتھ کے مطابق۔\n9۔ پھر میں دریا کے پار گورنروں کے پاس گیا، اور انہیں بادشاہ کے خطوط دیے۔ اب بادشاہ نے میرے ساتھ فوج کے کپتان اور گھڑ سوار بھیجے تھے۔\n10۔ جب حورونی سنبلات اور خادم، عمونی، طوبیا نے اس کی خبر سنی تو انہیں بہت دکھ ہوا کہ ایک آدمی بنی اسرائیل کی بھلائی کے لیے آیا ہے۔\n11۔ تو میں یروشلم آیا، اور وہاں تین دن رہا۔\n12۔ اور میں رات کو اٹھا، میں اور چند آدمی میرے ساتھ؛ نہ ہی میں نے {کسی نے} انسان کو بتایا کہ میرے خدا نے یروشلم میں میرے دل میں کیا رکھا ہے: نہ ہی میرے ساتھ کوئی درندہ تھا، سوائے اس جانور کے جس پر میں سوار تھا۔\n13۔ اور میں رات کو وادی کے دروازے سے، ڈریگن کے کنویں سے بھی پہلے، اور گوبر کے بندرگاہ تک گیا، اور یروشلم کی دیواریں دیکھیں، جو ٹوٹ چکی تھیں اور ان کے دروازے آگ میں جل چکے تھے۔\n14۔ پھر میں چشمے کے دروازے اور بادشاہ کے تالاب کی طرف گیا: لیکن {میرے نیچے جو درندہ تھا} کے لیے کوئی جگہ نہیں تھی کہ وہ گزر سکے۔\n15۔ پھر میں رات کو ندی کے کنارے گیا، دیوار کو دیکھا، پھر واپس مڑ کر وادی کے دروازے سے داخل ہوا، اور {یوں} واپس آیا۔\n16۔ اور حکمرانوں کو معلوم نہیں تھا کہ میں کہاں گیا، یا میں نے کیا کیا؛ نہ میں نے ابھی تک یہودیوں کو، نہ پادریوں کو، نہ اشرافیہ کو، نہ حکمرانوں کو، اور نہ ہی باقی لوگوں کو جو یہ کام کرتے تھے، بتایا تھا۔\n17۔ پھر میں نے ان سے کہا، تم دیکھ رہے ہو کہ ہم کس مصیبت میں ہیں، اور یروشلم ویرانی ہے، اور اس کے دروازے آگ سے جل رہے ہیں: آؤ، اور یروشلم کی دیوار تعمیر کرو، تاکہ ہم ملامت نہ رہیں۔\n18۔ پھر میں نے انہیں اپنے خدا کے ہاتھ کے بارے میں بتایا جو مجھ پر اچھا تھا؛ اور بادشاہ کے وہ الفاظ بھی جو اس نے مجھ سے کہے تھے۔ اور انہوں نے کہا، آؤ اٹھیں اور تعمیر کریں۔ لہٰذا انہوں نے اس {اچھے} {کام} کے لیے اپنے ہاتھ مضبوط کیے۔\n19۔ لیکن جب سنبلات حورونی اور ٹوبیاہ خادم، عمونی، اور گشم عرب نے یہ سنا، تو انہوں نے ہمیں مذاق اڑایا اور حقیر سمجھا، اور کہا، یہ کیا ہے جو تم کرتے ہو؟ کیا تم بادشاہ کے خلاف بغاوت کرو گے؟\n20۔ پھر میں نے انہیں جواب دیا اور کہا، آسمان کا خدا، وہ ہمیں خوشحال کرے گا؛ لہٰذا ہم اس کے خادم اٹھیں گے اور تعمیر کریں گے: لیکن یروشلم میں تمہارا کوئی حصہ، نہ حق، نہ یادگار۔","1۔ پھر الیاشیب، اعلیٰ کاہن، اپنے بھائیوں کے ساتھ کاہنوں کے ساتھ اٹھ کھڑا ہوا اور انہوں نے بھیڑ کا دروازہ بنایا؛ انہوں نے اسے مقدس قرار دیا، اور اس کے دروازے قائم کیے؛ حتیٰ کہ میاح کے مینار تک بھی انہوں نے اسے مقدس کیا، حنانیل کے مینار تک۔\n2۔ اور اس کے ساتھ ہی یریحو کے لوگ تعمیر ہوئے۔ اور ان کے ساتھ ہی زکری، امری کا بیٹا، تعمیر ہوا۔ {اگلا کہ...: عبرانی۔ اس کے ہاتھوں سے}\n3۔ لیکن مچھلی کا دروازہ حسینہ کے بیٹوں نے بنایا، جنہوں نے اس کے دروازے بچھائے، دروازے، تالے اور سلاخیں بھی بنائیں۔\n4۔ اور ان کے ساتھ مرموت، یوریاہ کا بیٹا، کوز کا بیٹا مرمت ہوا۔ اور ان کے ساتھ ہی مشعلم، برخیاہ کا بیٹا، مشیزبیل کا بیٹا، مرمت ہوا۔ اور ان کے ساتھ زادوق، بانا کا بیٹا، مرمت کر رہا تھا۔\n5۔ اور ان کے ساتھ ہی ٹیکوئٹس نے مرمت کی؛ لیکن ان کے اشرافیہ اپنے آقا کے کام میں اپنی گردن نہیں لگاتے۔\n6۔ مزید برآں، پرانے دروازے نے یہوعیعٰ، پسیعہ کے بیٹے، اور مشولم بسودییہ کے بیٹے کی مرمت کی؛ انہوں نے اس کے بیم بچھائے، دروازے، تالے اور سلاخیں نصب کیں۔\n7۔ اور ان کے ساتھ میلاتیا گبعونی اور جادون میرونوتھی، جو گبعون اور میزپا کے لوگ تھے، کو اس طرف دریا کے گورنر کے تخت پر بٹھایا۔\n8۔ اس کے ساتھ سنار کے کاریگروں کے ححایاہ کے بیٹے عزئیل کی مرمت ہوئی۔ اس کے ساتھ ہی حنانیہ، جو دوا سازوں میں سے ایک کا بیٹا تھا، نے بھی مرمت کی، اور انہوں نے یروشلم کو چوڑی دیوار تک مضبوط کیا۔ {قلعہ بندی...: یا، یروشلم چھوڑ کر چوڑی دیوار تک}\n9۔ اور ان کے ساتھ ہی رفیاہ، جو حور کا بیٹا تھا، یروشلم کے آدھے حصے کا حکمران تھا۔\n10۔ اور ان کے ساتھ ہی جدعیاہ بیٹا ہاروماف کے گھر کی مرمت کی۔ اور اس کے ساتھ حشبنیا کے بیٹے حتوش کی مرمت ہوئی۔\n11۔ ملکیاہ، حاریم کا بیٹا، اور ہاشوب بیٹا، پاہتھمواب کا، نے دوسرا ٹکڑا اور بھٹیوں کے مینار کی مرمت کی۔ {دیگر...: عبرانی۔ دوسرا پیمانہ}\n12۔ اور اس کے ساتھ ہی، حلوحش کے بیٹے شلوم، جو یروشلم کے آدھے حصے کا حکمران تھا، وہ اور اس کی بیٹیاں مرمت کر رہے تھے۔\n13۔ وادی کے دروازے نے حنون اور زانوح کے باشندوں کی مرمت کی؛ انہوں نے اسے بنایا، اس کے دروازے، اس کے تالے اور اس کی سلاخیں، اور گوبر کے دروازے کی دیوار پر ہزار کیوبٹس بنائے۔\n14۔ لیکن گوبر کے دروازے نے مالکیا کی مرمت کی، جو بیت حکرم کے کچھ حصے کے حکمران ریخاب کا بیٹا تھا؛ اس نے اسے تعمیر کیا، اور اس کے دروازے، تالے اور سلاخیں نصب کیں۔\n15۔ لیکن چشمے کے دروازے نے شالون، کولہوزہ کا بیٹا، جو مزپا کے ایک حصے کا حکمران تھا، کو مرمت کر دیا؛ اس نے اسے تعمیر کیا، ڈھانپ دیا، اور اس کے دروازے، تالے اور اس کی سلاخیں، اور بادشاہ کے باغ کے قریب سیلوح کے تالاب کی دیوار، اور داؤد کے شہر سے نیچے جانے والی سیڑھیوں تک نصب کیا۔\n16۔ اس کے بعد نحمیاہ بیٹا، ازبوک کا بیٹا، بیت زور کے آدھے حصے کا حکمران، داؤد کی قبروں کے سامنے اور اس تالاب کے پاس جو بنایا گیا تھا، اور طاقتور خاندان کی مرمت کی۔\n17۔ اس کے بعد لاویوں کی مرمت کی، بنی کے بیٹے رحوم۔ اس کے ساتھ ہیشبیاہ بھی تھا، جو کیلہ کے آدھے حصے کا حکمران تھا۔\n18۔ اس کے بعد اس نے اپنے بھائیوں، ہیناداد کے بیٹے باوائی کی مرمت کی، جو کیلہ کے نصف حصے کا حکمران تھا۔\n19۔ اور اس کے ساتھ یشوع کا بیٹا، مزپا کا حکمران، ایزر کی مرمت کر رہا تھا، ایک اور ٹکڑا جو دیوار کے مڑنے والے ہتھیار خانے کی طرف جاتا تھا۔\n20۔ اس کے بعد زبائی کے بیٹے باروخ نے دوسرا ٹکڑا سنجیدگی سے مرمت کیا، جو دیوار کے موڑنے سے لے کر اعلیٰ کاہن کے گھر کے دروازے تک جاتا ہے۔ {زبائی: جسے زکائی بھی کہا جاتا ہے}\n21۔ اس کے بعد اس نے یوریاہ کے بیٹے میرموتھ کو ایک اور ٹکڑا مرمت کیا، جو ایلیاشیب کے گھر کے دروازے سے لے کر ایلیاشیب کے گھر کے آخر تک پہنچا۔\n22۔ اور اس کے بعد پادریوں کو ٹھیک کیا، جو میدان کے لوگ تھے۔\n23۔ اس کے بعد اس نے بنجمن اور ہاشوب کو ان کے گھر کے ساتھ مرمت کیا۔ اس کے بعد اس نے عزریہ، جو عاسیا کا بیٹا تھا، اس کے گھر سے مرمت کی۔\n24۔ اس کے بعد ہیناداد کے بیٹے بنوئی کو ایک اور ٹکڑا مرمت کیا، جو عزریاہ کے گھر سے دیوار کے موڑ تک اور کونے تک تھا۔\n25۔ پالال، اوزائی کا بیٹا، دیوار کے مڑنے کے سامنے اور اس مینار کے سامنے جو بادشاہ کے اعلیٰ گھر سے نکلا ہے، جو قید خانے کے دربار کے پاس تھا۔ اس کے بعد پیدایاہ جو پاروش کا بیٹا تھا۔\n26۔ مزید برآں، نیتھینیم اوفیل میں رہتے تھے، جو مشرق کی طرف پانی کے دروازے اور اس مینار کے سامنے واقع تھا۔ {رہتا...: یا، جو اوفیل میں رہتا تھا، مرمت کیا گیا} {اوفیل: یا، مینار}\n27۔ ان کے بعد ٹیکوئٹس نے ایک اور ٹکڑا مرمت کیا، جو عظیم مینار کے ساتھ اوفیل کی دیوار تک پھیلا ہوا ہے۔\n28۔ گھوڑے کے دروازے کے اوپر سے پادریوں کو ٹھیک کیا گیا، ہر ایک اس کے گھر کے سامنے کھڑا تھا۔\n29۔ ان کے بعد انہوں نے زدوک، میر کے بیٹے، کو اس کے گھر کے خلاف مرمت کیا۔ اس کے بعد شمعیہ، شحنیا کا بیٹا، مشرقی دروازے کا محافظ بھی ٹھیک ہوا۔\n30۔ اس کے بعد شلیمیاہ کے بیٹے حنانیاہ اور زالف کے چھٹے بیٹے حنون کی مرمت کی گئی، ایک اور ٹکڑا۔ اس کے بعد مشولم، جو بریخیاہ کا بیٹا تھا، اس کے کمرے کے سامنے کھڑا کر دیا۔\n31۔ اس کے بعد مالکیا سنار کے بیٹے کو نیتھینیمز اور تاجروں کی جگہ پر ٹھیک کیا، جو میفکاد کے دروازے کے پاس اور کونے کے اوپر جانے والے حصے تک تھا۔ {جا رہا ہے...: یا، کونے کے کمرے میں}\n32۔ اور کونے سے بھیڑ کے دروازے تک جانے کے درمیان سونے کے کاریگر اور تاجروں کی مرمت ہوئی۔ {جا رہا ہے...: یا، کونے کے کمرے میں}","1۔ لیکن ایسا ہوا کہ جب سنبلات نے سنا کہ ہم نے دیوار بنائی ہے، تو وہ غصے میں آ گیا، بہت غصے میں آ گیا، اور یہودیوں کا مذاق اڑایا۔\n2۔ اور اس نے اپنے بھائیوں اور سامریہ کی فوج کے سامنے کہا اور کہا، یہ کمزور یہودی کیا کر رہے ہیں؟ کیا وہ خود کو مضبوط کریں گے؟ کیا وہ قربانی دیں گے؟ کیا وہ ایک دن میں ختم ہو جائیں گے؟ کیا وہ جلائے گئے کچرے کے ڈھیر سے پتھروں کو زندہ کریں گے؟ {مضبوط...: عبرانی۔ اپنے آپ پر چھوڑ دیں}\n3۔ اب توبیا عمونی اس کے پاس تھا، اور اس نے کہا، جو کچھ بھی وہ بناتے ہیں، اگر لومڑی اوپر جائے تو وہ ان کی پتھر کی دیوار بھی توڑ دے گا۔\n4. سن لو، اے ہمارے خدا؛ کیونکہ ہم حقیر ہیں: اور ان کی ملامت ان کے سر پر الٹ دیتے ہیں، اور انہیں قید کی سرزمین میں شکار کے طور پر پیش کرتے ہیں: {حقیر: عبرانی۔ اس کے باوجود}\n5۔ اور ان کے گناہوں کو نہ چھپاؤ، اور ان کا گناہ تمہارے سامنے چھپایا نہ جائے، کیونکہ انہوں نے تمہیں معماروں کے سامنے غصہ دلایا ہے۔\n6. یوں ہم نے دیوار بنائی؛ اور ساری دیوار اس کے آدھے حصے سے جڑ گئی: کیونکہ لوگوں کا کام کرنے کا ارادہ تھا۔\n7۔ لیکن ایسا ہوا کہ جب سنبلاط، طوبیا، عربوں، عمونیوں اور اشدودیوں نے سنا کہ یروشلم کی دیواریں بنائی گئی ہیں، اور دراڑیں بند ہونے لگیں، تو وہ بہت غصے میں آ گئے، بن گئے۔ عروج پر پہنچا}\n8۔ اور سب کو مل کر سازش کی کہ وہ یروشلم کے خلاف لڑیں اور اسے روکیں۔ {رکاوٹ ڈالنے کے لیے...: عبرانی۔ غلطی کرنے کے لیے}\n9۔ پھر بھی ہم نے اپنے خدا سے دعا کی، اور دن رات ان کے خلاف پہرہ دی، ان کی وجہ سے۔\n10۔ اور یہوداہ نے کہا، بوجھ اٹھانے والوں کی طاقت کمزور ہو گئی ہے، اور بہت سا فضول مواد ہے؛ تاکہ ہم دیوار نہ بنا سکیں۔\n11۔ اور ہمارے مخالفین نے کہا، وہ نہیں جان پائیں گے، نہ دیکھیں گے، جب تک ہم ان کے درمیان نہ آ کر انہیں قتل نہ کریں اور کام روک نہ دیں۔\n12۔ اور ایسا ہوا کہ جب ان کے پاس رہنے والے یہودی آئے، تو انہوں نے ہم سے دس بار کہا، ہر جگہ سے جہاں سے تم ہمارے پاس واپس آؤ گے {وہ تم پر ہوں گے}۔ {سب سے...: یا، ہر جگہ سے تمہیں ہمارے پاس واپس جانا ہوگا}\n13. اسی لیے میں نے دیوار کے پیچھے نچلی جگہوں پر رکھا، {اور} اونچی جگہوں پر، یہاں تک کہ لوگوں کو ان کے خاندانوں کے پیچھے تلواریں، نیزے اور کمانیں لگا دیں۔ {میں...: عبرانی میں۔ جگہ کے نچلے حصے سے، وغیرہ}\n14۔ اور میں نے دیکھا، اٹھ کھڑا ہوا، اور اشرافیہ، حکمرانوں، اور باقی لوگوں سے کہا، ان سے مت ڈرو: خداوند کو یاد رکھو، جو عظیم اور خوفناک ہے، اور اپنے بھائیوں، بیٹوں، بیٹیوں، بیویوں اور اپنے گھروں کے لیے لڑو۔\n15۔ اور ایسا ہوا جب ہمارے دشمنوں نے سنا کہ ہمیں معلوم ہے اور خدا نے ان کی نصیحت کو بے کار کر دیا ہے، تو ہم سب کو دیوار کی طرف لوٹا دیا، ہر ایک اپنے کام کی طرف۔\n16۔ اور اس وقت سے یہ ہوا کہ میرے آدھے خادم اس کام میں مصروف تھے، اور باقی آدھے نے نیزے، ڈھالیں، کمانیں اور ہابرجن دونوں پکڑے ہوئے تھے؛ اور حکمران تمام یہوداہ خاندان کے پیچھے تھے۔\n17۔ وہ جو دیوار پر تعمیر کرتے تھے، اور جو بوجھ اٹھاتے تھے، جو سامان اٹھاتے تھے، {ہر ایک} اپنے ایک ہاتھ سے کام میں اور دوسرے ہاتھ سے ہتھیار تھامے ہوئے۔\n18۔ تعمیر کرنے والوں کے لیے، ہر ایک نے اپنی تلوار اپنے پہلو میں بندھی ہوئی تھی، اور {اتنی} تعمیر کی گئی۔ اور جس نے ٹرمپٹ بجایا وہ میرے پاس تھا۔ {اس کے ساتھ: عبرانی۔ اس کی کمر کے بلے}\n19۔ اور میں نے اشرافیہ، حکمرانوں، اور باقی لوگوں سے کہا، کام {ہے} عظیم اور بڑا، اور ہم دیوار پر جدا ہیں، ایک دوسرے سے دور۔\n20۔ جس جگہ {لہٰذا} تم بگل کی آواز سنو گے، وہاں ہمارے پاس آؤ: ہمارا خدا ہمارے لیے لڑے گا۔\n21. تو ہم نے محنت کی: اور ان میں سے آدھے نے صبح سے لے کر ستاروں کے نمودار ہونے تک نیزے پکڑے رہے۔\n22۔ اسی وقت میں نے لوگوں سے کہا، ہر کوئی اپنے خادم کے ساتھ یروشلم میں ٹھہرے، تاکہ رات کو وہ ہمارے پہرے دار بن کر دن میں محنت کرے۔\n23. تو نہ میں، نہ میرے بھائی، نہ میرے خادم، نہ وہ محافظ جو میرے پیچھے تھے، ہم میں سے کوئی بھی اپنے کپڑے نہیں اتارتا، {سوائے اس کے} کہ سب نے انہیں دھونے کے لیے اتار دیا۔ {محفوظ کر رہا ہے...: یا، ہر کوئی پانی کے لیے اپنے ہتھیار کے ساتھ گیا}","1۔ اور لوگوں اور ان کی بیویوں کی طرف سے اپنے بھائیوں یہودیوں کے خلاف ایک بڑا نعرہ بلند ہوا۔\n2۔ کیونکہ کہا گیا، ہم، ہمارے بیٹے اور ہماری بیٹیاں، بہت ہیں: اس لیے ہم ان کے لیے اناج اگاتے ہیں تاکہ ہم کھا سکیں اور زندہ رہیں۔\n3۔ {کچھ} نے یہ بھی کہا کہ ہم نے اپنی زمینیں، انگور کے باغات، اور گھر گروی رکھ دیے ہیں تاکہ ہم مکئی خرید سکیں، کیونکہ اس کی کمی ہے۔\n4۔ یہ بھی کہا گیا، ہم نے بادشاہ کے خراج کے لیے پیسے ادھار لیے ہیں، {اور وہ بھی} ہماری زمینوں اور انگور کے باغات پر۔\n5. پھر بھی اب ہمارا جسم {ہے} ہمارے بھائیوں کے گوشت کی طرح، ہمارے بچے ان کے بچوں کی طرح: اور دیکھو، ہم اپنے بیٹوں اور بیٹیوں کو غلام بناتے ہیں، اور {کچھ} ہماری بیٹیوں کو {پہلے ہی} غلامی میں لایا جاتا ہے: نہ ہی {یہ} ہمارے اختیار میں {انہیں نجات دینا}؛ کیونکہ دوسرے لوگوں کے پاس ہماری زمینیں اور انگور کے باغات ہیں۔\n6۔ اور جب میں نے ان کی چیخ اور یہ الفاظ سنا تو میں بہت غصے میں آ گیا۔\n7۔ پھر میں نے خود سے مشورہ کیا، اور اشرافیہ اور حکمرانوں کو ڈانٹا، اور ان سے کہا، تم اس کے ہر بھائی پر سود لیتے ہو۔ اور میں نے ان کے خلاف ایک بڑی مجلس کھڑی کی۔ {میں نے مشورہ کیا...: عبرانی۔ میرا دل مجھ سے مشورہ کرتا ہے}\n8۔ اور میں نے ان سے کہا، ہم نے اپنی صلاحیت کے مطابق اپنے بھائیوں کو یہودیوں کو نجات دی جو کافروں کو بیچ دیے گئے تھے؛ اور کیا تم اپنے بھائیوں کو بھی بیچ دو گے؟ یا انہیں ہمیں بیچ دیا جائے گا؟ پھر انہوں نے خاموش رکھا، اور جواب دینے کے لیے کچھ نہ پایا۔\n9۔ میں نے یہ بھی کہا، یہ اچھا نہیں ہے جو تم کرتے ہو: کیا تمہیں ہمارے دشمن کافروں کی ملامت کی وجہ سے ہمارے خدا کے خوف میں نہیں چلنا چاہیے؟\n10۔ میں بھی، {اور} اپنے بھائیوں اور میرے خادموں، ان سے پیسے اور اناج لے سکتا ہوں: میں آپ سے درخواست کرتا ہوں، اس سود کو چھوڑ دیں۔\n11۔ میں تم سے درخواست کرتا ہوں کہ آج بھی، ان کی زمینیں، ان کے انگور کے باغات، ان کے زیتونوں کے باغات، اور ان کے گھروں کو بحال کرو، اور ساتھ ہی ان سے حاصل کیے گئے پیسے کا سوسواں حصہ، مکئی، شراب، اور تیل بھی۔\n12۔ پھر انہوں نے کہا، ہم انہیں واپس کریں گے، اور ان سے کچھ نہیں مانگے گے؛ اسی طرح ہم وہی کریں گے جو آپ کہیں گے۔ پھر میں نے پادریوں کو بلایا اور ان سے قسم لی کہ وہ اس وعدے کے مطابق عمل کریں۔\n13۔ میں نے اپنی گود ہلائی اور کہا، تو خدا ہر اس آدمی کو اس کے گھر اور اس کی محنت سے نکال دے، جو یہ وعدہ پورا نہیں کرتا، یوں ہی وہ ہل جائے اور خالی ہو جائے۔ اور تمام جماعت نے کہا، آمین، اور خداوند کی تعریف کی۔ اور لوگوں نے اس وعدے کے مطابق ایسا کیا۔ {خالی: عبرانی۔ خالی، یا، خلا}\n14۔ مزید برآں، جب سے مجھے یہوداہ کی سرزمین میں ان کا گورنر مقرر کیا گیا، بیسویں سال سے لے کر آرتخشیر بادشاہ کے دو اور تیسویں سال تک، بارہ سال، میں اور میرے بھائیوں نے گورنر کی روٹی نہیں کھائی۔\n15۔ لیکن جو سابق حکمران {مجھ سے} پہلے تھے، عوام کے ذمہ دار تھے، اور انہوں نے ان میں سے روٹی اور شراب لے لی، چالیس شیکل چاندی کے علاوہ؛ ہاں، یہاں تک کہ ان کے خادم بھی لوگوں پر حکمرانی کرتے ہیں: لیکن میں نے ایسا نہیں کیا، خدا کے خوف کی وجہ سے۔\n16۔ ہاں، میں نے بھی اس دیوار کا کام جاری رکھا، ہم نے کوئی زمین نہیں خریدی: اور میرے تمام خادم وہاں کام کے لیے جمع ہو گئے۔\n17. مزید برآں میرے دسترخوان پر ایک سو پچاس یہودی اور حکمران موجود تھے، ان کے علاوہ جو ہمارے ارد گرد موجود مشرکین میں سے آئے تھے۔\n18۔ اب وہ {و} جو {میرے لیے} روزانہ تیار کیا گیا {تھا} ایک بیل {اور} چھ منتخب بھیڑیں؛ میرے لیے بھی مرغیاں تیار کی جاتیں، اور ہر دس دن میں ہر قسم کی شراب ذخیرہ کی جاتی تھی، لیکن اس سب کے باوجود مجھے گورنر کی روٹی کی ضرورت نہیں تھی، کیونکہ غلامی اس قوم پر بھاری تھی۔\n19. میرے خدا، میرے خدا کے لیے، میرے اوپر بھلائی کے لیے سوچو، {ان سب کے مطابق جو میں نے اس قوم کے لیے کیا ہے۔","1۔ اب یہ ہوا جب سنبلاط، طوبیاہ، اور گشم عرب، اور ہمارے باقی دشمنوں نے سنا کہ میں نے دیوار تعمیر کر دی ہے، اور اس میں کوئی دراڑ باقی نہیں رہی؛ (اگرچہ اس وقت میں نے دروازے دروازے نہیں لگائے تھے؛)\n2۔ جو سنبلات اور گشیم نے میرے پاس بھیجا، کہا، آؤ، ہم اونو کے میدان کے کسی گاؤں میں مل کر ملیں۔ لیکن انہوں نے مجھے شرارت کرنے کا سوچا۔\n3۔ اور میں نے ان کے پاس قاصد بھیجے، کہا کہ میں ایک عظیم کام کر رہا ہوں، اس لیے میں نیچے نہیں آ سکتا: کام کیوں رکے جب میں اسے چھوڑ کر تمہارے پاس آؤں؟\n4۔ پھر بھی انہوں نے اس قسم کے بعد چار بار مجھے بھیجا؛ اور میں نے بھی اسی انداز میں جواب دیا۔\n5۔ پھر پانچویں بار اپنے خادم سنبلات کو بھی اسی طرح میرے پاس ایک کھلا خط لے کر بھیجا؛\n6۔ جس میں {لکھا} گیا ہے، یہ غیر مسلموں میں بیان کیا گیا ہے، اور گاشمو کہتا ہے {یہ} کہ تم اور یہودی بغاوت کرنے کا ارادہ رکھتے ہو: اسی لیے تم دیوار بناتے ہو، تاکہ تم ان کا بادشاہ بن سکو، ان الفاظ کے مطابق۔ {گاشمو: جسے گشم بھی کہا جاتا ہے}\n7۔ اور تم نے یروشلم میں تمہاری تبلیغ کے لیے نبیوں کو بھی مقرر کیا ہے، اور کہا ہے، یہوداہ میں بادشاہ ہے: اور اب یہ بات بادشاہ کو ان الفاظ کے مطابق بتائی جائے گی۔ تو اب آؤ، اور ہم مل کر مشورہ کرتے ہیں۔\n8۔ پھر میں نے اس کے پاس بھیجا، کہا، تم جو کہتی ہو وہ کچھ نہیں ہوتی، لیکن تم دل سے دکھاوا کرتی ہو۔\n9۔ کیونکہ انہوں نے ہمیں ڈرا دیا تھا، کہتے ہوئے، ان کے ہاتھ کام سے کمزور ہو جائیں گے، تاکہ یہ نہ کیا جائے۔ اب {اے خدا}، میرے ہاتھوں کو مضبوط فرما۔\n10۔ بعد میں شمعیہ کے گھر آیا، جو دلایا کا بیٹا محتابیل کا بیٹا تھا، جو خاموش تھا؛ اور اس نے کہا، آؤ ہم خدا کے گھر میں، مندر کے اندر مل کر ملیں اور مندر کے دروازے بند کر دیں: کیونکہ وہ تمہیں مارنے آئیں گے؛ ہاں، رات کو وہ تمہیں مارنے آئیں گے۔\n11۔ اور میں نے کہا، کیا میرے جیسے آدمی کو بھاگ جانا چاہیے؟ اور کون ہے جو، جیسا کہ میں ہوں، مندر میں اپنی جان بچانے کے لیے جائے؟ میں اندر نہیں جاؤں گا۔\n12۔ اور، دیکھو، میں نے محسوس کیا کہ خدا نے اسے نہیں بھیجا؛ بلکہ اس نے یہ پیش گوئی میرے خلاف کہی: کیونکہ طوبیا اور سنبلات نے اسے ملازمت دی تھی۔\n13. اسی لیے {تھا} اس نے مجھے اس لیے رکھا کہ میں ڈروں، اور ایسا کروں، اور گناہ کروں، اور {تاکہ} وہ {برا واقعہ} حاصل کر لیں، تاکہ وہ مجھے ملامت کریں۔\n14۔ میرے خدا، توبیا اور سنبلات کو ان کے اعمال کے مطابق، اور نبی نودیاہ اور باقی نبیوں کے بارے میں سوچو، جو مجھے خوفزدہ کر دیتے۔\n15۔ یوں دیوار مہینے ایلول کے پچیس دن میں پچاس اور دو دن میں مکمل ہوئی۔\n16۔ اور ایسا ہوا کہ جب ہمارے تمام دشمنوں نے اس کے بارے میں سنا، اور ہمارے ارد گرد موجود تمام کافروں نے {یہ باتیں} دیکھیں، تو وہ اپنی آنکھوں میں بہت مایوس ہو گئے: کیونکہ انہوں نے سمجھا کہ یہ کام ہمارے خدا کا انجام ہے۔\n17۔ اس کے علاوہ ان دنوں یہوداہ کے اشرافیہ نے توبیاہ کو کئی خطوط بھیجے، اور {توبیا کے خطوط} ان تک پہنچے۔ {بھیجا...: عبوری۔ ان کے خطوط توبیا تک پہنچ گئے}\n18۔ کیونکہ یہوداہ میں بہت سے لوگ تھے جنہوں نے اس کی قسم کھائی تھی، کیونکہ وہ آرہ کے بیٹے شحنیا کا داماد تھا؛ اور اس کا بیٹا یوحنان مشولم کی بیٹی بریخیاہ کی بیٹی کو لے گیا تھا۔\n19۔ انہوں نے اس کے اچھے کاموں کی اطلاع میرے سامنے دی، اور میرے الفاظ اس سے کہے۔ {اور} توبیا نے مجھے خوفزدہ کرنے کے لیے خطوط بھیجے۔ {الفاظ: یا، اہمیت رکھتا ہے}","1۔ اب یہ ہوا، جب دیوار بنائی گئی، اور میں نے دروازے لگا دیے، اور پورٹر، گانے والے اور لاوی مقرر کیے گئے،\n2۔ کہ میں نے اپنے بھائی حنانی اور محل کے حکمران حنانیاہ کو یروشلم کی ذمہ داری دی: کیونکہ وہ ایک وفادار آدمی تھا، اور خدا سے بہت سے زیادہ خوف رکھتا تھا۔\n3۔ اور میں نے ان سے کہا، یروشلم کے دروازے سورج کے گرم ہونے تک نہ کھلیں؛ اور جب وہ کھڑے ہوں، تو دروازے بند کر دیں اور انہیں روک دیں: اور یروشلم کے باشندوں کی پہرہ دار مقرر کریں، ہر ایک اپنی پہرہ میں، اور ہر کوئی اپنے گھر کے خلاف کھڑا ہو۔\n4. اب شہر {تھا} بڑا اور عظیم تھا: لیکن وہاں کے لوگ {ات} کم تھے، اور گھر {بنے} نہیں گئے تھے۔ {بڑا: عبوری۔ وسیع جگہوں میں}\n5۔ اور میرے خدا نے میرے دل میں رکھا تاکہ اشرافیہ، حکمرانوں اور لوگوں کو اکٹھا کروں، تاکہ وہ نسب کے مطابق شمار کیے جا سکیں۔ اور میں نے ان کی نسب نامہ کا ایک رجسٹر پایا جو پہلے سامنے آیا، اور اس میں لکھا ہوا پایا،\n6۔ یہ وہ لوگ ہیں جو اس صوبے کے بچے ہیں، جو قید سے نکلے گئے، جنہیں بابل کے بادشاہ نبوکدنصر نے لے جایا تھا، اور پھر یروشلم اور یہوداہ واپس آئے، ہر ایک اپنے شہر میں؛\n7. جو زروبابل، یشوع، نحمیا، عزریہ، رامیاہ، نہمانی، مردخائی، بلشان، مسپیریتھ، بگوائی، نہوم، بعنا کے ساتھ آیا۔ {میں کہتا ہوں} بنی اسرائیل کے مردوں کی تعداد {یہ تھی}؛ {آزاریا: جسے سرایاہ بھی کہا جاتا ہے}\n8۔ پروش کے بچے، دو ہزار ایک سو ستر بیا۔\n9۔ شیفطیا کے بچے، تین سو ستر اور بیا۔\n10۔ آرہ کے بچے، چھ سو پچاس بیا۔\n11۔ پحثمواب کے بچے، یشوع اور یوآب کے بچوں میں، دو ہزار آٹھ سو اور اٹھارہ۔\n12۔ ایلام کے بچے، ہزار دو سو پچاس چار۔\n13۔ زاتو کے بچے، آٹھ سو پینتالیس سال کے۔\nچودہ۔ زکائی کے بچے، سات سو تین۔\n15۔ بنوئی کے بچے، چھ سو اڑتالیس سال۔ {بنوی: جسے بانی بھی کہا جاتا ہے}\n16۔ بیبائی کے بچے، چھ سو بیس اٹھائیس۔\n17۔ ازگد کے بچے، دو ہزار تین سو بائیس۔\n18۔ اڈونیکم کے بچے، چھ سو تینٹھ اور سات۔\nانیس۔ بیگوئی کے بچے، دو ہزار تینٹھ سات۔\n20۔ عدن کے بچے، چھ سو پچاس پینچ۔\n21۔ حزقیاہ کے آتر کے بچے، نوے اور اٹھانوے۔\n22۔ ہاشم کے بچے، تین سو بیس اٹھائیس۔\n23۔ بیزائی کے بچے، تین سو بیس چوبیس۔\n24۔ حاریف کے بچے، ایک سو بارہ۔ {حارف: جسے جورا بھی کہا جاتا ہے}\n25۔ گیبئون کے بچے، پچانوے سال کے۔ {گیبیون: جسے گبار بھی کہا جاتا ہے}\n26۔ بیت لحم اور نیتوفاہ کے مرد، ایک سو چوغانٹھ آٹھ۔\n27۔ اناتھوتھ کے لوگ، ایک سو اٹھائیس۔\n28۔ بیتھازماویت کے مرد، بیالیس اور بیالیس۔ {بیتھازماویتھ: جسے ازماوتھ بھی کہا جاتا ہے}\n29۔ کیرجاتجاریم، چفیرا، اور بیروت کے لوگ، سات سو چالیس تین۔ {کرجاتجاریم: جسے کرجاتھاریم بھی کہا جاتا ہے}\n30۔ رامہ اور گبا کے لوگ، چھ سو بیس اکیس۔\n31۔ میخماس کے مرد، ایک سو بیس اور بائیس۔\n32۔ بیت ایل اور آئی کے لوگ، ایک سو بیس اور تین۔\n33۔ دوسرے نیبو کے مرد، پچاس اور بیا۔\n34۔ دوسرے ایلام کے بچے، ہزار دو سو پچاس چار۔\n35۔ حریم کے بچے، تین سو بیس۔\n36۔ یریحو کے بچے، تین سو پینتالیس سال۔\n37۔ لود، حدید اور اونو کے بچے، سات سو بیس اکیس۔\n38۔ سیناہ کے بچے، تین ہزار انیس سو تیس۔\n39۔ کاہن: یشع کے گھرانے کے جدایہ کے بچے، نو سو سترہ تین۔\n40۔ مر کے بچے، ہزار پچاس اور بیا۔\n41۔ پاشور کے بچے، ہزار دو سو چالیس سین۔\n42۔ حاریم کے بچے، ہزار سترہ۔\n43۔ لاوی: یشوع کے بیٹے، کادمیئل، {اور} ہودیوا کے بچوں کے بیٹے، ستر اور چون۔ {ہودیوا: جسے ہوداویاہ یا یہوداہ بھی کہا جاتا ہے}\n44۔ گلوکار: آساف کے بچے، ایک سو اڑتالیس سال۔\n45۔ دربان: شلوم کے بچے، آتر کے بچے، تلمون کے بچے، عکوب کے بچے، حتیتا کے بچے، شوبائی کے بچے، ایک سو تیس اٹھائی۔\n46۔ نیتھینیمز: زیہا کے بچے، ہاشوفا کے بچے، تاباوت کے بچے،\n47۔ کیروس کے بچے، سیا کے بچے، پیڈون کے بچے،\n48۔ لبنان کے بچے، حجابا کے بچے، شلمائی کے بچے،\n49۔ حنان کے بیٹے، گدل کے بچے، گاہر کے اولاد،\n50۔ ریعیاہ کے بچے، ریزین کے بچے، نیکودا کے بچے،\n51۔ غزام کے بچے، عزا کے بیٹے، فسیح کے بچے،\n52۔ بیسائی کے بچے، میونیم کے بچے، نیفیشیسم کے بچے،\n53۔ بکبک کے بچے، حکوفا کے بچے، ہارہر کے بچے،\n54۔ بزلیت کے بچے، مہدہ کے بچے، ہرشہ کے بچے،\n55۔ بارکوس کے بچے، سیسرا کے بچے، تامہ کے بچے،\n56۔ نزیہ کے بچے، حتیفا کے بچے۔\n57۔ سلیمان کے خادموں کے بچے: سوتائی کے بچے، سوفریت کے بچے، پریدہ کے بچے،\n58۔ جالا کے بچے، ڈارکن کے بچے، گڈل کے بچے،\n59۔ شفاطیاہ کے بچے، حتیل کے بچے، زبائیم کے پوکیرتھ کے بچے، آمون کے بچے۔ {آمون: جسے آمی بھی کہا جاتا ہے}\n60۔ تمام نیتھینیمز، اور سلیمان کے خادموں کے بچے تین سو نوے اور دو سال کے تھے۔\n61۔ اور یہ وہ لوگ تھے جو تلمیلہ، تلہاریشا، کروب، عدون اور ایمر سے بھی اوپر گئے: لیکن وہ اپنے باپ کے گھر یا اپنی نسل کو نہیں دکھا سکتے تھے کہ وہ اسرائیل کے ہیں یا نہیں۔ {بیج: یا، نسل}\n62۔ ڈیلایاہ کے بچے، توبیا کے بچے، نیکوڈا کے بچے، چھ سو بیالیس اور بیا۔\n63۔ اور کاہنوں کی: حبیاہ کے بیٹے، کوز کے بچے، برزیلائی کے بچے، جنہوں نے برزیلائی گلیڈائی کی بیٹیوں میں سے ایک کو بیوی بنایا اور ان کے نام سے پکارا گیا۔\n64۔ یہ لوگ ان لوگوں میں سے رجسٹر کرنے کی کوشش کرتے تھے جنہیں نسب نامہ کے لحاظ سے شمار کیا جاتا تھا، لیکن وہ نہیں ملا: اسی لیے وہ ناپاک ہو کر پادریوں سے نکال دیے گئے۔\n65۔ اور تیرشتھا نے ان سے کہا کہ وہ سب سے مقدس چیزوں میں سے نہ کھائیں جب تک کہ ایک پادری اوریم اور تھمم کے ساتھ کھڑا نہ ہو جائے۔ {تیرشاتھا: یا، گورنر}\n66۔ پوری جماعت مل کر چالیس دو ہزار تین سو تین سو پر مشتمل تھی،\n67۔ ان کے نوکروں اور نوکرانیوں کے علاوہ، جن میں سے سات ہزار تین سو تیس سات تھے: اور ان کے پاس دو سو چالیس پانچ گانے والے مرد اور گانے والی عورتیں تھیں۔\n68۔ ان کے گھوڑے، سات سو تیس چھے: ان کے خچر، دو سو چالیس اور پانچ:\n69۔ {ان} اونٹ، چار سو تیس پانچ: چھ ہزار سات سو بیس گدھے۔\n70۔ اور بزرگوں میں سے کچھ نے اس کام میں حصہ لیا۔ تیرشتھا نے خزانے کو ہزار ڈرم سونا، پچاس بسونز، پانچ سو تیس پجاریوں کے لباس دیے۔ {کچھ: عبرانی۔ حصہ۔} {تیرشاتھا: یا، گورنر}\n71۔ اور بزرگوں میں سے کچھ نے کام کے خزانے کو بیس ہزار ڈرم سونا اور دو ہزار دو سو پاؤنڈ چاندی دی۔\n72۔ اور جو باقی لوگوں نے دیا وہ بیس ہزار ڈرم سونا، دو ہزار پاؤنڈ چاندی، اور تیس سات پادریوں کے کپڑے تھے۔\n73۔ یوں کاہن، لاوی، دربان، گانے والے، اور کچھ لوگ، نیتھینیم، اور تمام اسرائیل، اپنے شہروں میں بسے؛ اور جب ساتواں مہینہ آیا، تو بنی اسرائیل اپنے شہروں میں تھے۔","1۔ اور تمام لوگ ایک آدمی کی طرح اس گلی میں جمع ہو گئے جو پانی کے دروازے کے سامنے تھی؛ اور انہوں نے عزرا کاتب سے کہا کہ وہ موسیٰ کے قانون کی کتاب لے آئے، جسے خداوند نے اسرائیل تک حکم دیا تھا۔\n2۔ اور عزرا پادری نے ساتویں مہینے کے پہلے دن شریعت کو جماعت کے سامنے پیش کیا، مردوں اور عورتوں دونوں کے سامنے، اور جو سب سمجھداری سے سن سکتے تھے۔ {وہ...: عببرانی۔ جو سننے میں سمجھ آئے}\n3۔ اور اس نے اس گلی کے سامنے پڑھا جو صبح سے دوپہر تک پانی کے دروازے کے سامنے تھی، مردوں اور عورتوں اور سمجھنے والوں کے سامنے؛ اور تمام لوگوں کے کان {قانون کی کتاب پر توجہ دے رہے تھے}۔ {سے...: عبرانی روشنی سے}\n4۔ اور عزرا کاتب لکڑی کے منبر پر کھڑا تھا، جو انہوں نے اس مقصد کے لیے بنایا تھا؛ اور اس کے دائیں ہاتھ پر متیتیا، شمع، حنایہ، اوریاہ، حلقیا، اور ماسیہ کھڑے تھے؛ اور اس کے بائیں ہاتھ پر، پدعیہ، مشائل، مالکیاہ، ہاشوم، حشبدانا، زکریا اور، مشلم۔ {منبر...: عبرانی۔ ٹاور آف ووڈ}\n5۔ اور عزرا نے سب لوگوں کی نظر میں کتاب کھول دی؛ (کیونکہ وہ سب لوگوں سے بالاتر تھا؛) اور جب اس نے دروازہ کھولا، تو سب لوگ کھڑے ہو گئے: {منظر: عبرانی۔ آنکھیں}\n6۔ اور عزرا نے خداوند کو برکت دی، جو عظیم خدا ہے۔ اور سب لوگوں نے جواب دیا، آمین، آمین، ہاتھ اٹھا کر: اور انہوں نے سر جھکا کر خداوند کی عبادت کی، {اپنے} چہرے زمین پر رکھ کر۔\n7۔ اسی طرح یشوع، اور بانی، اور شریبیاہ، یمین، عکوب، شبتائی، ہودیجہ، ماسیہیہ، کلیتا، عزریہ، یوزآباد، حنان، پلعیاہ اور لاویوں نے لوگوں کو شریعت سمجھائی: اور لوگ ان کی جگہ کھڑے ہو گئے۔\n8۔ تو انہوں نے کتاب میں خدا کے قانون کو واضح طور پر پڑھا، اور معنی دیے، اور {ان} کو پڑھائی کو سمجھا۔\n9۔ اور نحمیا، جو تیرشتھا ہے، اور عزرا کاہن، کاتب، اور لاوی جو لوگوں کو تعلیم دیتے تھے، سب لوگوں سے کہا، آج کا دن خداوند تمہارے خدا کے لیے مقدس ہے؛ نہ ماتم کرو، نہ روؤ۔ کیونکہ سب لوگ شریعت کے الفاظ سن کر رو پڑے۔ {تیرشاتھا: یا، گورنر}\n10۔ پھر اس نے ان سے کہا، اپنا راستہ چلو، چربی کھاؤ، میٹھا پیو، اور ان کے لیے کچھ بھیجو جن کے لیے کچھ تیار نہیں کیا گیا: کیونکہ یہ دن ہمارے رب کے لیے مقدس ہے: تم افسوس نہ کرو؛ کیونکہ خداوند کی خوشی تمہاری طاقت ہے۔\n11۔ یوں لاویوں نے سب لوگوں کو خاموش کر دیا، کہا، خاموش رہو، کیونکہ دن {مقدس} ہے؛ نہ ہی تم غمگین ہو۔\n12۔ اور سب لوگ کھانے، پینے، حصے بھیجنے، اور بڑی خوشی منانے کے لیے روانہ ہوئے، کیونکہ انہوں نے ان سے کہی گئی باتوں کو سمجھ لیا تھا۔\n13۔ اور دوسرے دن سب لوگوں کے بزرگوں، یعنی کاہنوں اور لاویوں کو عزرا کاتب کے سامنے جمع کیا گیا، تاکہ وہ شریعت کے الفاظ سمجھ سکیں۔ {سمجھنے کے لیے...: یا، تاکہ وہ قانون کے الفاظ میں تعلیم دے سکیں}\n14۔ اور انہوں نے اس قانون میں لکھا پایا جو خداوند نے موسیٰ نے حکم دیا تھا، کہ بنی اسرائیل ساتویں مہینے کے تہوار پر بوتھوں میں رہیں: {از عبرانی۔ ہاتھوں سے}\n15۔ اور وہ اپنے تمام شہروں اور یروشلم میں اعلان کریں اور اعلان کریں، اور پہاڑ پر جاؤ، اور زیتون کی شاخیں، صنوبر کی شاخیں، مرٹل کی شاخیں، کھجور کی شاخیں، اور گھنے درختوں کی شاخیں لے آؤ، تاکہ بوتھیں بنائی جا سکیں، جیسا کہ {لکھا ہے}۔\n16۔ تو لوگ باہر نکلے، انہیں لے آئے، اور اپنے گھر کی چھت پر، اپنے صحنوں میں، اور خدا کے گھر کے صحنوں میں، پانی کے دروازے کی گلی میں، اور افریم کے دروازے کی گلی میں اپنے لیے بوتھ بنا لیے۔\n17۔ اور ان سب کی جماعت جو قید سے واپس آئے، انہوں نے بوتھز بنائے اور ان کے نیچے بیٹھ گئے: کیونکہ یشوع نون کے بیٹے کے زمانے سے لے کر آج تک بنی اسرائیل نے ایسا نہیں کیا تھا۔ اور بہت خوشی ہوئی۔\n18۔ اسی طرح دن بہ دن، پہلے دن سے آخری دن تک، وہ خدا کے قانون کی کتاب میں پڑھتا رہا۔ اور انہوں نے سات دن عید منایا؛ اور آٹھویں دن ایک باوقار اجتماع ہوا، جیسا کہ طریقہ کار تھا۔ {ایک سنجیدہ...: عبرانی۔ ایک روک تھام}","1۔ اب اس مہینے کے چوبیس دن اسرائیل کے بچوں کو روزہ، تھیلے اور مٹی کے ساتھ جمع کیا گیا۔\n2۔ اور اسرائیل کی نسل نے خود کو تمام اجنبیوں سے جدا کیا، اور کھڑے ہو کر اپنے گناہوں اور اپنے باپ اجداد کے گناہوں کا اعتراف کیا۔ {اجنبی: عبرانی۔ عجیب بچے}\n3۔ اور وہ اپنی جگہ کھڑے ہوئے، اور دن کے چوتھائی حصے میں خداوند کے خدا کے قانون کی کتاب میں پڑھا؛ اور {ایک اور} چوتھے حصے میں انہوں نے اعتراف کیا، اور اپنے خدا خداوند کی عبادت کی۔\n4۔ پھر وہ لاویوں کی سیڑھیوں پر کھڑے ہوئے، جو لاویوں، یشوع، اور بانی، کادمیئل، سبانیا، بنی، {اور} چنانی کی تھی، اور بلند آواز میں خداوند ان کے خدا کو پکارا۔ {سیڑھیاں: یا، سکیفولڈ}\n5۔ پھر لاویوں، یشوع، اور کادمیئل، بانی، ہشبنیاہ، شیربیاہ، ہودیجہ، شبانیاہ، {اور} پتھاحیاہ نے کہا، کھڑے ہو جاؤ {اور} خداوند اپنے خدا کو ہمیشہ ہمیشہ کے لیے برکت دے: اور تیرا جلال مند نام مبارک ہو، جو ہر نعمت اور تعریف سے بلند ہے۔\n6۔ تو، {حتی} تو، {ہو} واحد رب؛ تو نے آسمان کو بنایا ہے، آسمانوں کا آسمان، ان کے تمام لشکر کے ساتھ، زمین، اور اس میں موجود تمام چیزیں، سمندروں اور اس میں جو کچھ بھی ہے، اور تم ان سب کی حفاظت کرتے ہو؛ اور آسمان کی فوج تمہاری عبادت کرتی ہے۔\n7۔ تو خداوند خدا ہو، جس نے ابرام کو چنا، اور اسے کلدیوں میں سے یور سے نکالا اور اسے ابراہیم کا نام دیا؛\n8۔ اور اس کے دل کو تمہارے سامنے وفادار پایا، اور اس کے ساتھ عہد کیا کہ کنعانیوں، حتیوں، اموریوں، پیرزیوں، یبوسیوں، اور گرگاشیوں کی زمین کو دے دوں گا، تاکہ {یہ، میں کہتا ہوں} اس کی نسل کو دے دے، اور تمہارے الفاظ پورے کیے؛ کیونکہ تو {راستباز} ہو:\n9۔ اور مصر میں اپنے آباؤ اجداد کی مصیبت دیکھی، اور ان کی پکار سنی؛\n10۔ اور اس نے فرعون، اس کے تمام خادموں، اور اس کی زمین کے تمام لوگوں پر علامات اور عجائبات دکھائیں، کیونکہ تم جانتے تھے کہ وہ ان کے خلاف غرور کرتے ہیں۔ اسی طرح تمہیں ایک نام ملا، جیسا کہ آج ہے۔\n11۔ اور تو نے ان کے سامنے سمندر کو تقسیم کیا، تاکہ وہ خشکی سے سمندر کے بیچ سے گزر گئے؛ اور ان کے ستکرنے والوں کو تم نے گہرائیوں میں پھینک دیا، جیسے پتھر عظیم پانیوں میں۔\n12۔ مزید برآں، تم دن میں انہیں ایک بادلوں والے ستون کے پاس لے جاتے ہو؛ اور رات کو آگ کے ستون کے پاس، تاکہ انہیں اس راستے میں روشنی ملے جہاں وہ جانا چاہیے۔\n13۔ تم بھی کوہ سینا پر اترے اور آسمان سے ان سے بات کی، اور انہیں صحیح فیصلے، سچے قوانین، اچھے قوانین اور احکامات دیے: {سچ...: عبرانی۔ سچائی کے قوانین}\n14۔ اور سب سے زیادہ جنونی طور پر ان کے لیے تمہاری مقدس سبت کو جانا، اور انہیں اپنے خادم موسیٰ کے ہاتھوں احکامات، قوانین اور احکامات کا حکم دیا:\n15۔ اور ان کی بھوک کے لیے آسمان سے روٹی دی، اور ان کی پیاس کے لیے چٹان سے پانی نکالا، اور انہیں وعدہ کیا کہ وہ اس زمین پر قبضہ کرنے جائیں گے جو تم نے انہیں دینے کی قسم کھائی تھی۔ {جو کہ...: عبرانی جو تم نے انہیں دینے کے لیے اپنا ہاتھ اٹھایا تھا}\n16۔ لیکن انہوں نے اور ہمارے باپ اجداد نے غرور سے کام کیا، اپنی گردنیں سخت کیں، اور تیرے احکامات کی پیروی نہیں کی،\n17۔ اور اطاعت سے انکار کیا، نہ ہی اپنے عجائبات کا خیال رکھا جو تم نے ان میں کیا؛ لیکن ان کی گردنیں سخت کیں، اور بغاوت میں ایک کپتان مقرر کیا جو ان کی غلامی میں واپس آئے: لیکن تو ایک خدا ہو جو معاف کرنے کو تیار ہے، مہربان اور رحم دل، غصے میں سست اور بہت مہربانی، اور انہیں ترک نہیں کرتے۔ {ایک خدا...: عبرانی۔ معافی کا خدا}\n18۔ ہاں، جب انہوں نے انہیں پگھلا ہوا بچھڑا بنایا اور کہا، یہ تمہارا خدا ہے جس نے تمہیں مصر سے نکالا اور بڑی اشتعال انگیزی کی؛\n19۔ پھر بھی تم اپنی بے پناہ رحمتوں میں انہیں بیابان میں نہیں چھوڑتے: بادل کا ستون دن میں ان سے دور نہیں ہٹا، تاکہ انہیں راستے میں لے جائے؛ نہ رات کے وقت آگ کا ستون، تاکہ انہیں روشنی دکھائی جائے، اور نہ ہی وہ راستہ جس میں وہ جانا چاہیے۔\n20۔ تم نے اپنی نیک روح بھی دی کہ انہیں تعلیم دے، اور اپنی من ان کے منہ سے نہ روکے، اور ان کی پیاس کے لیے پانی دیا۔\n21۔ جی ہاں، تم نے انہیں چالیس سال ویرانے میں سہارا دیا، {یہاں تک کہ} ان کے پاس کچھ کمی نہ رہی؛ ان کے کپڑے پرانے نہیں تھے، اور ان کے پاؤں پھول نہیں رہے تھے۔\n22۔ مزید یہ کہ تم نے انہیں بادشاہتیں اور قومیں عطا کیں، اور انہیں کونوں میں تقسیم کیا: یوں وہ سیہون کی زمین، ہیشبون کے بادشاہ کی زمین، اور باشان کے بادشاہ اوگ کی زمین پر قابض تھے۔\n23۔ ان کے بچوں نے بھی آسمان کے ستاروں کی طرح بڑھایا، اور انہیں اس زمین میں لے آئے، جس کے بارے میں تم نے ان کے باپوں سے وعدہ کیا تھا کہ وہ اس زمین پر قبضہ کرنے آئیں گے۔\n24۔ تو بچے اندر گئے اور زمین پر قبضہ کر لیا، اور تم نے ان کے سامنے زمین کے باشندوں، کنعانیوں کو زیر کر دیا، اور انہیں ان کے ہاتھوں، ان کے بادشاہوں اور اس سرزمین کے لوگوں کے حوالے کر دیا، تاکہ وہ ان کے ساتھ جیسا چاہیں کر سکیں۔ {جب وہ...: عبرانی۔ ان کی وصیت کے مطابق}\n25۔ اور انہوں نے مضبوط شہر، موٹی زمین لی، اور تمام مالوں سے بھرے مکانات، کنویں کھودے، انگور کے باغات، زیتون کے باغات، اور پھلوں کے درخت وافر مقدار میں حاصل کیے، تو وہ کھائے، بھر گئے، موٹے ہو گئے، اور تیری عظیم نیکی پر خوش ہوئے۔ {ویلز: یا، ذخیرہ} {پھل...: عبرانی۔ خوراک کا درخت}\n26۔ پھر بھی وہ نافرمان تھے، اور تمہارے خلاف بغاوت کی، تیری شریعت کو اپنی پیٹھ کے پیچھے پھینک دیا، اور تمہارے نبیوں کو قتل کر دیا جو ان کے خلاف گواہی دے رہے تھے تاکہ انہیں تمہاری طرف موڑ سکیں، اور انہوں نے بڑی اشتعال انگیزی کی۔\n27۔ اس لیے تم نے انہیں ان کے دشمنوں کے ہاتھ میں دے دیا، جنہوں نے انہیں پریشان کیا: اور ان کے مصیبت کے وقت جب وہ تم سے پکارے، تو نے آسمان سے ان کی آواز سنی؛ اور اپنی بے شمار رحمتوں کے مطابق تو نے انہیں نجات دہندہ دیے، جنہوں نے انہیں دشمنوں کے ہاتھوں سے بچایا۔\n28۔ لیکن جب وہ آرام کر چکے تھے، تو انہوں نے آپ کے سامنے دوبارہ برا کیا: اس لیے کیا آپ نے انہیں ان کے دشمنوں کے ہاتھوں چھوڑ دیا، تاکہ ان پر حکمرانی حاصل ہو گئی ہو، لیکن جب وہ واپس آئے اور آپ کو پکارا، تو آپ نے آسمان سے ان کی آواز سنائی؛ اور کئی بار تم نے اپنی مہربانی کے مطابق انہیں نجات دی؛ {انہوں نے...: عبرانی۔ وہ برائی کرنے کے لیے واپس آئے}\n29۔ اور اس نے ان کے خلاف گواہی دی تاکہ تم انہیں دوبارہ اپنے قانون کے تابع کر سکو، لیکن انہوں نے غرور سے پیش آئے، اور تمہارے احکامات کی سنائی نہیں دی، بلکہ تمہارے فیصلوں کے خلاف گناہ کیا، (جو اگر انسان کرے گا تو وہ ان میں زندہ رہے گا؛) اور کندھے کو پیچھے کیا، اپنی گردن سخت کی، اور سننے کو تیار نہیں تھا۔ {پیچھے ہٹنا...: عبرانی۔ انہوں نے کندھا پیچھے ہٹا دیا}\n30۔ پھر بھی کئی سال تک تم نے انہیں برداشت کیا، اور اپنے نبیوں میں اپنی روح سے ان کے خلاف گواہی دی، لیکن وہ سننے کو تیار نہیں تھے، اس لیے انہیں زمینوں کے لوگوں کے ہاتھ میں دے دو۔ {forbear...: عبرانی۔ ان پر تفصیل دیں} {اپنے...: عبرانی میں۔ تمہارے نبیوں کے ہاتھ میں}\n31۔ پھر بھی اپنی عظیم رحمتوں کے لیے تم نے انہیں مکمل طور پر نہیں کھایا، نہ ہی چھوڑا؛ کیونکہ تو ایک مہربان اور رحم دل خدا ہے۔\n32۔ لہٰذا اب ہمارے خدا، عظیم، طاقتور اور خوفناک خدا، جو عہد اور رحم کی پاسداری کرتا ہے، تمام مصیبتیں تیرے سامنے چھوٹی نہ لگے، جو ہم پر، ہمارے بادشاہوں، ہمارے بادشاہوں، ہمارے کاہنوں، ہمارے نبیوں پر، ہمارے باپوں پر، اور تمہارے تمام لوگوں پر آئی ہیں، جو آشور کے بادشاہوں کے زمانے سے آج تک آئی ہیں۔ {مسئلہ: عبوری۔ تھکن} {وہ...: عبرانی۔ جس نے ہمیں ڈھونڈ لیا ہے}\n33۔ اگرچہ تم ہم پر آنے والی ہر چیز میں عادل ہو؛ کیونکہ تم نے نیکی کی ہے، لیکن ہم نے برے کام کیے ہیں:\n34۔ نہ تو ہمارے بادشاہوں، نہ بادشاہوں، نہ کاہنوں، اور نہ ہی ہمارے باپ اجداد، نہ ہی تیری شریعت کی پاسداری کی، نہ ہی تمہارے احکامات اور گواہیوں کو سنا جن سے تم نے ان کے خلاف گواہی دی۔\n35۔ کیونکہ انہوں نے اپنی بادشاہت میں تمہاری خدمت نہیں کی، اور نہ ہی تمہاری بڑی بھلائی میں جو تم نے انہیں دی، اور اس وسیع اور موٹی زمین میں جو تم نے ان کے سامنے دی، نہ ہی انہوں نے اپنے برے اعمال سے دور کیا۔\n36۔ دیکھو، ہم آج خادم ہیں، اور اس زمین کے لیے جو تم نے ہمارے آباؤ اجداد کو دی تاکہ وہ اس کا پھل اور اس کی بھلائی کھائیں، دیکھو، ہم اس میں خادم ہیں:\n37۔ اور یہ ان بادشاہوں کے لیے بہت فائدہ مند ہے جنہیں تم نے ہمارے گناہوں کی وجہ سے ہم پر مقرر کیا ہے، اور وہ ہمارے جسموں اور مویشیوں پر بھی ان کی مرضی سے حکمرانی کرتے ہیں، اور ہم شدید مصیبت میں ہیں۔\n38۔ اور اس سب کی وجہ سے ہم ایک یقینی {عہد} کرتے ہیں، اور {it} لکھتے ہیں؛ اور ہمارے شہزادے، لاوی، {اور} کاہن، {اس پر مہر لگاؤ}۔ {مہر: عبرانی مہر بند کر رہے ہیں، یا، سیل کیے گئے ہیں}","1۔ اب جن لوگوں نے {مہر لگائی} وہ تھے: نحمیا، تیرشتھا، حخالیہ کا بیٹا، اور زدکیاہ، {وہ...: عبرانی۔ سیلنگز پر} {تیرشاتھا: یا، گورنر}\n2. سریاہ، عزریا، یرمیا،\n3۔ پاشور، اماریہ، ملکیجاہ،\n4۔ ہتوش، شبانیاہ، مالوخ،\n5۔ ہاریم، میرموتھ، اوبدیا،\n6۔ ڈینیئل، گنیتھن، باروخ،\n7۔ مشمولم، ابیجہ، میامین،\n8. معزیہ، بلگائی، شمعیہ: یہ {تھے} کاہن۔\n9۔ اور لاوی: دونوں یشوع، عزانیہ کا بیٹا، حناداد کے بیٹوں کا بنوی، کادمیئل؛\n10۔ اور ان کے بھائی، سبانیاہ، ہودیجہ، کلیتا، پیلاہ، حنان،\n11۔ میخا، ریہوب، حشبیہ،\n12۔ زکور، شیریبیاہ، شبانیاہ،\n13۔ ہودیجہ، بانی، بینینو۔\n14۔ عوام کا سردار؛ پروش، پاہتھموآب، ایلام، زتھو، بانی،\n15۔ بنی، ازگد، بیبائی،\n16۔ ادونیاہ، بگوائی، عدن،\n17. آتر، حزکیجہ، آزور،\n18۔ حدیجہ، ہاشوم، بیزائی،\n19۔ حارف، اناتھوتھ، نیبائی،\n20۔ مگپیاش، مشمولم، ہزیر،\n21. مشیزابیل، زادوک، جدوا،\n22. پیلاطیہ، حنان، عنایا،\n23. ہوشع، حنانیہ، ہشب،\n24۔ ہالوہیش، پیلیہ، شوبیک،\n25. رحوم، حشبنہ، ماسیہ،\n26۔ اور آہیجہ، حنان، عنان،\n27۔ مالوخ، حاریم، بعناہ۔\n28۔ اور باقی لوگ، کاہن، لاوی، دربان، گانے والے، نیتھینیم، اور وہ سب جو خدا کے قانون کے تابع زمین کے لوگوں سے الگ ہو چکے تھے، ان کی بیویاں، ان کے بیٹے اور بیٹیاں، ہر ایک کے پاس علم اور سمجھ تھا؛\n29۔ وہ اپنے بھائیوں، اپنے اشرافیہ کے سامنے چلیں گے، اور خدا کے قانون کے مطابق چلنے اور خدا کے بندے موسیٰ کی طرف سے دیا گیا خدا کے قانون پر چلنے اور خداوند ہمارے رب کے تمام احکام، اس کے فیصلوں اور قوانین کی پابندی اور عمل کرنے کی کوشش کرتے ہیں؛ {بذریعہ: عبرانی ہاتھوں سے}\n30۔ اور کہ ہم اپنی بیٹیوں کو زمین کے لوگوں کے حوالے نہیں کریں گے، اور نہ ہی ان کی بیٹیوں کو اپنے بیٹے بنائیں گے:\n31۔ اور اگر زمین کے لوگ ہفتہ کے دن سامان یا کوئی چیز بیچنے کے لیے لاتے ہیں، تو ہم انہیں ہفتہ یا مقدس دن نہیں خریدیں گے: اور ہم ساتویں سال اور ہر قرض کی ادائیگی چھوڑ دیں گے۔ {ہر...: عبرانی۔ ہر ہاتھ}\n32. ہم نے اپنے لیے بھی عہد نامے بنائے کہ ہم ہر سال اپنے خدا کے گھر کی خدمت کے لیے ایک تیسرا شیکل وصول کریں؛\n33۔ روٹی کے لیے، اور مسلسل گوشت کی قربانی، اور مسلسل جلنے کی قربانی، سبت کے دنوں، نئے چاندوں کی، مقررہ تہواروں کے لیے، مقدس چیزوں کے لیے، اور گناہ کی قربانیوں کے لیے جو اسرائیل کے لیے کفارہ ہیں، اور ہمارے خدا کے گھر کے تمام کاموں کے لیے۔\n34۔ اور ہم نے یہ قرعہ کاہنوں، لاویوں اور لوگوں کے درمیان لکڑی کی قربانی کے طور پر پھینکا، تاکہ اسے ہمارے خدا کے گھر میں لایا جا سکے، ہمارے باپ اجداد کے گھروں کے بعد، جو کبھی کبھار سال بہ سال مقرر کیے گئے تھے، خداوند ہمارے خدا کے مذبح پر جلنے کے لیے، جیسا کہ شریعت میں لکھا ہے:\n35۔ اور اپنی زمین کے پہلے پھل، اور تمام درختوں کے تمام پھلوں کے پہلے پھل، سال بہ سال، خداوند کے گھر تک پہنچانا:\n36۔ اور ہمارے بیٹوں اور ہمارے مویشیوں میں سے سب سے بڑا اولاد، جیسا کہ شریعت میں لکھا ہے، اور ہمارے ریوڑ اور ریوڑ کے نخستہ بچے بھی، تاکہ وہ ہمارے خدا کے گھر میں ان کاہنوں کو لے آئیں جو ہمارے خدا کے گھر میں خدمت کرتے ہیں:\n37۔ اور {تاکہ} ہم اپنے آٹے کے پہلے پھل، اپنی نذراں، اور ہر قسم کے درختوں، شراب اور تیل کے پھل کاہنوں کے لیے، اپنے خدا کے گھر کے کمروں میں لائیں۔ اور ہماری زمین کی عشر لاویوں کو دے دیتی ہے، تاکہ وہی لاوی ہمارے کھیت کے تمام شہروں میں عشر حاصل کر سکیں۔\n38۔ اور ہارون کا بیٹا کاهن لاویوں کے ساتھ ہوگا، جب لاوی عشر لیں گے: اور لاوی عشر ہمارے خدا کے گھر، کمروں میں، خزانے کے گھر میں لائیں گے۔\n39۔ کیونکہ بنی اسرائیل اور لاوی کے بچے اناج کی پیشکش، نئی شراب، اور تیل کو کمروں میں لائیں گے، جہاں مقدس مقام کے برتن، خدمت کرنے والے کاہن، اور دربان اور گانے والے ہیں: اور ہم اپنے خدا کے گھر کو نہیں چھوڑیں گے۔","1۔ اور قوم کے حکمران یروشلم میں مقیم تھے: باقی لوگوں نے بھی قرعہ اندازی کی، تاکہ دس میں سے ایک کو یروشلم میں مقدس شہر اور نو حصے {دیگر} شہروں میں رہنے کے لیے لایا جا سکے۔\n2۔ اور لوگوں نے ان تمام مردوں کو برکت دی جو خود کو خوش دلی سے یروشلم میں رہنے کی پیشکش کرتے تھے۔\n3۔ اب یہ سب یروشلم میں رہنے والے صوبے کے سردار ہیں: لیکن یہوداہ کے شہروں میں ہر کوئی اپنے شہروں میں رہتا تھا، یعنی اسرائیل، کاہن، لاوی، نیتھینیم، اور سلیمان کے خادموں کی اولاد۔\n4۔ اور یروشلم میں یہوداہ کے بچوں اور بنیامین کے بچوں میں سے کچھ رہتے۔ یہوداہ کے بچوں سے؛ اتھیا عزیہ کا بیٹا تھا، زکریا کا بیٹا، امریاہ کا بیٹا، شیفطیہ کا بیٹا، مہلالیل کا بیٹا، پیریز کے بچوں سے؛ {پیریز: جسے فاریز بھی کہا جاتا ہے}\n5۔ اور ماسیہیہ، باروخ کا بیٹا، کولہوزہ کا بیٹا، حزیاہ کا بیٹا، عدیاہ کا بیٹا، جویاریب کا بیٹا، زکریا کا بیٹا، شیلونی کا بیٹا۔\n6۔ یروشلم میں رہنے والے پیریز کے تمام بیٹے چار سو تیس اور آٹھ بہادر تھے۔\n7۔ اور یہ {ہیں} بنیامین کے بیٹے؛ سالو، مشولام کا بیٹا، جود کا بیٹا، پیدعیاہ کا بیٹا، کولایاہ کا بیٹا، ماسیہ کا بیٹا، یسعیاہ کا بیٹا۔\n8۔ اور اس کے بعد گبائی، سلائی، نو سو بیس اٹھائیس۔\n9۔ اور یوئیل، زکری کا بیٹا، ان کا نگران تھا: اور یہوداہ سنوع کا بیٹا شہر کا دوسرا تھا۔\n10۔ کاہنوں میں: جدیدیہ، جویاریب کا بیٹا، یچن۔\n11۔ سریعہ ہلکیاہ کا بیٹا، مشولم کا بیٹا، زادوک کا بیٹا، میرایوت کا بیٹا، آہیتوب کا بیٹا، خدا کے گھر کا حکمران تھا۔\n12۔ اور ان کے بھائی جو گھر کا کام کرتے تھے، آٹھ سو بیس تھے: اور عدیاہ، یروہام کا بیٹا، پیلالیاہ کا بیٹا، امزی کا بیٹا، زکریا کا بیٹا، پاشور کا بیٹا، مالکیا کا بیٹا،\n13۔ اور اس کے بھائی، باپ کے سردار، دو سو بیالیس: اور اماشائی، آزاریل کا بیٹا، اہاسائی کا بیٹا، میشیلموتھ کا بیٹا، ایمر کا بیٹا،\n14۔ اور ان کے بھائی، بہادر آدمی، سو اٹھائیس: اور ان کے نگران زبدیئل تھے، جو عظیم لوگوں میں سے ایک کا بیٹا تھا۔ {بیٹا...: یا، ہیگڈولم کا بیٹا}\n15۔ لاویوں کا بھی: شمعیہ، ہاشوب کا بیٹا، عزریکم کا بیٹا، حشبیاہ کا بیٹا، بنی کا بیٹا؛\n16۔ اور شبتائی اور یوزآباد، جو لاویوں کے سردار تھے، خدا کے گھر کے بیرونی معاملات کی نگرانی کرتے تھے۔ {تھا...: عبرانی ختم ہو چکا تھا}\n17۔ اور متانیا، میخا کا بیٹا، زبدی کا بیٹا، عصفوف کا بیٹا، {تھا} دعا میں شکرگزاری کا آغاز کرنے والا پرنسپل تھا؛ اور بکبوکیا اپنے بھائیوں میں دوسرا تھا، اور عبدا شموعہ کا بیٹا، جلال کا بیٹا، جدوتون کا بیٹا۔\n18۔ مقدس شہر کے تمام لاوی دو سو چوداہ چار تھے۔\n19۔ اس کے علاوہ دربان، عکوب، تلمون، اور ان کے بھائی جو دروازے کے محافظ تھے، ایک سو ستر اور دو تھے۔ {دروازے: عبرانی۔ دروازوں پر}\n20۔ اور اسرائیل، کاہنوں، اور لاویوں کی باقیات یہوداہ کے تمام شہروں میں موجود تھیں، ہر ایک اپنی میراث میں۔\n21. لیکن نیتھینیم اوفل میں رہتے تھے: اور زیہا اور گسپا نیتھینم کے اوپر تھے۔ {اوفل: یا، مینار}\n22۔ یروشلم میں لاویوں کا بھی نگران عوزی تھا، جو بنی کا بیٹا تھا، حشبہیا کا بیٹا، متانیاہ کا بیٹا، میخا کا بیٹا۔ آساف کے بیٹوں میں سے گانے والے خدا کے گھر کے معاملات میں مصروف تھے۔\n23۔ کیونکہ بادشاہ کا ان کے بارے میں حکم تھا کہ ایک مخصوص حصہ گلوکاروں کے لیے ہو، جو ہر دن کے لیے واجب الادا ہو۔ {ایک خاص...: یا، ایک یقینی آرڈیننس}\n24۔ اور پتھاحیاہ، مشیزبیل کا بیٹا، زراہ کے بیٹے یہوداہ کے بیٹے میں سے بادشاہ کے ہاتھوں لوگوں کے تمام معاملات میں تھا۔ {زراہ: جسے زارہ بھی کہا جاتا ہے}\n25۔ اور ان دیہاتوں کے لیے، جن کے کھیتوں کے ساتھ، یہوداہ کے کچھ بچے کرجاتھاربا میں رہتے تھے، اور ان کے دیہات، اور دیبون کے دیہات، اور یکابزیل میں، اور ان کے دیہات میں،\n26۔ اور یشوع پر، اور مولادہ پر، اور بیت فلیت میں،\n27۔ اور ہزارشوال میں، اور بیر شبع میں، اور اس کے گاؤں میں،\n28۔ اور زیکلاگ پر، اور میکونا پر، اور ان کے دیہات میں،\n29۔ اور اینریمون پر، اور زاریہ پر، اور یارموت میں،\n30۔ زانواح، عدولم، اور ان کے دیہات، لاخیش اور ان کے کھیتوں، عزیقہ میں، اور ان کے دیہات میں۔ اور وہ بیرشبع سے ہنوم وادی تک آباد تھے۔\n31۔ بنیامین کے بچے بھی گبا سے {رہت} میخماش، آیجا، اور بیت ال میں، اور {ان کے گاؤں میں} {سے: یا، of} {at: or, to}\n32. {اور} اناتھوتھ، نوب، عنانیاہ،\n33۔ حزور، رامہ، گٹائم،\n34۔ حدید، زبوئیم، نبالات،\n35۔ لود، اور اونو، کاریگروں کی وادی۔\n36۔ اور لاویوں میں {یہوداہ میں} تقسیمات تھے، {اور} بنیامین میں۔","1۔ اب یہ وہ کاہن اور لاوی ہیں جو زروبابل بیٹے شلتیئل اور یشوع کے ساتھ اوپر گئے: سرایاہ، یرمیا، عزرا،\n2۔ اماریہ، مالوچ، ہتوش، {مالوچ: جسے میلیکو بھی کہا جاتا ہے}\n3. شحنیاہ، رحم، میرموتھ، {شحنیاہ: جسے شیبانیاہ بھی کہا جاتا ہے} {رحم: جسے حریم بھی کہا جاتا ہے} {میرموتھ: جسے میریوتھ بھی کہا جاتا ہے}\n4. ایدو، گنیتھو، ابیجہ، {گنیتھو: جسے گنیتھن بھی کہا جاتا ہے}\n5. میامین، معادیہ، بلگاہ، {میامین: جسے مینیامین بھی کہا جاتا ہے} {معادیہ: جسے معادیہ بھی کہا جاتا ہے}\n6۔ شمعیہ، اور جویاریب، جدیدیہ،\n7. سالو، اموک، ہلکیاہ، جدایہ۔ یہ یشوع کے زمانے میں کاہنوں اور ان کے بھائیوں کے سردار تھے۔ {سالو: جسے سلائی بھی کہا جاتا ہے}\n8۔ مزید لاوی لوگ: یشوع، بنوی، کادمیئل، شیریبیا، یہوداہ، {اور} متانیا، {جو تھا} شکرگزاری کے موقع پر، وہ اور اس کے بھائی۔ {تھینکس گیونگ: یعنی، تھینکس گیونگ کے زبور}\n9۔ اسی طرح بکبوکیا اور انی، ان کے بھائی، بھی گھڑیوں میں ان کے خلاف تھے۔\n10۔ اور یشوع نے جویاکیم کو جنم دیا، یویاقیم نے بھی الیاشیب، اور الیاشیب نے جویاعا کو جنم دیا،\n11۔ اور جویادا نے یوناتھن کو جنم دیا، اور یوناتھن نے جدوا کو جنم دیا۔\n12۔ اور جویاکیم کے زمانے میں پادری تھے، جو بزرگوں میں سے سردار تھے: سریاہ کے، میرایا؛ یرمیاہ، حنانیاہ کی؛\n13۔ عزرا، مشولم کی؛ اماریہ، یہوحانان؛\n14۔ میلیکو، جوناتھن؛ شیبانیا، جوزف؛\n15۔ ہریم، عدنا؛ میرایوتھ، ہیلکائی؛\n16۔ ادو کی، زکریا؛ جنیتھن، مشولم کے؛\n17۔ ابیجہ، زکری کی؛ منیامین، معادیہ، پلتائی کے؛\n18۔ بلگاہ، شموعہ کی؛ شمعیہ، یہوناتھن؛\n19۔ اور جویاریب، متینائی؛ جدیدیہ، اوزی؛\n20۔ سلائی، کالائی؛ اموک، ایبر کی؛\n21۔ ہلکیا، حشبیہ؛ جدیدیہ، نیتھانیل۔\n22۔ الیاشب، جویادا، اور یوحنان کے زمانے میں لاوی اور جدوعہ کو داریوس فارسی کے دور حکومت میں باپوں کے سردار کے طور پر درج کیا گیا تھا۔\n23۔ لاوی کے بیٹے، جو بزرگوں میں سے سردار تھے، {تواریخوں کی کتاب} میں لکھے گئے، یہاں تک کہ یوحنان الیاشیب کے بیٹے کے زمانے تک۔\n24۔ اور لاویوں کے سردار: حشبیاہ، شیریبیا، اور یشوع ابن کادمیئل، اپنے بھائیوں کے ساتھ، ان کے خلاف تعریف کرنے اور شکر ادا کرنے کے لیے، خدا کے آدمی داؤد کے حکم کے مطابق، دفاع کے خلاف کھڑا رہو۔\n25۔ متانیا، اور بکبوکیا، عوبدیہ، مشمولم، تلمون، عکوب، {درمیان} تھے جو دروازوں کے دروازے پر حفاظتی حصار رکھتے تھے۔ {تھریشولڈز: یا، خزانے، یا، اسمبلیز}\n26۔ یہ یعقوب کے زمانے میں تھے، یشوع کا بیٹا، یوزادک کا بیٹا، اور نحمیاہ گورنر کے زمانے میں، اور عزرا کاہن، کاتب کے زمانے میں۔\n27۔ اور یروشلم کی دیوار کی وقف کے موقع پر انہوں نے لاویوں کو ان کی تمام جگہوں سے نکالنے کی کوشش کی، انہیں یروشلم لے جانے کے لیے، تاکہ وہ خوشی سے وقف ہو سکیں، شکرگزاری کے ساتھ اور گانے کے ساتھ، جھنجھن، زبور اور ہارپ کے ساتھ۔\n28۔ اور گانے والوں کے بیٹوں نے خود کو جمع کیا، یروشلم کے آس پاس کے میدانی علاقے سے اور نیتوفاتی کے دیہات سے؛\n29۔ گلگل کے گھرانے سے، اور گبا اور عزماوت کے کھیتوں سے: کیونکہ گلوکاروں نے یروشلم کے ارد گرد گاؤں بنائے تھے۔\n30۔ اور کاہنوں اور لاویوں نے خود کو پاک کیا، اور لوگ، دروازے اور دیوار کو پاک کیا۔\n31۔ پھر میں نے یہوداہ کے شہزادوں کو دیوار پر اٹھایا، اور دو بڑی جماعتیں مقرر کیں جنہوں نے شکر ادا کیا، {جن میں سے ایک} دائیں طرف دیوار پر گوبر کے دروازے کی طرف گئی:\n32۔ اور ان کے بعد ہوشیا اور یہوداہ کے آدھے شہزادے گئے،\n33۔ اور عزریہ، عزرا، اور مشولم،\n34۔ یہوداہ، اور بنیمن، اور شمعیہ، اور یرمیاہ،\n35۔ اور {کچھ پادریوں کے بیٹوں میں سے کچھ جن کے پاس بگل تھے؛' {یعنی}، زکریا جو یوناتھن کا بیٹا تھا، جو شمعیہ کا بیٹا تھا، متانیاہ کا بیٹا، میخیا کا بیٹا، زکور کا بیٹا، جو آساف کا بیٹا تھا:\n36۔ اور اس کے بھائی، شمعیہ، عزرائیل، ملالائی، گیلالای، مائی، نیتھانیل، اور یہوداہ، حنانی، داؤد خدا کے آدمی کے موسیقی کے آلات کے ساتھ، اور عزرا کاتب ان کے سامنے۔\n37۔ اور فوارے کے دروازے پر، جو ان کے سامنے تھا، وہ داؤد شہر کی سیڑھیوں سے اوپر گئے، دیوار کے اوپر چڑھتے ہوئے، داؤد کے گھر کے اوپر، یہاں تک کہ مشرق کی طرف پانی کے دروازے تک۔\n38۔ اور ان میں سے دوسرا {جو شکر ادا کرتا تھا} ان کے خلاف گیا، اور میں ان کے پیچھے گیا، اور دیوار پر موجود آدھے لوگوں کے ساتھ، بھٹیوں کے مینار کے پار سے چوڑی دیوار تک؛\n39۔ اور افرائیم کے دروازے کے اوپر، اور پرانے دروازے کے اوپر، مچھلی کے دروازے کے اوپر، حنانیل کے مینار سے، اور میہ کے مینار سے، بھیڑ کے دروازے تک، اور وہ قید خانے کے دروازے میں ساکت کھڑے رہے۔\n40۔ خدا کے گھر میں وہ دو {گروہ جنہوں نے شکر ادا کیا} کھڑے تھے، اور میں، اور میرے ساتھ حکمرانوں کے آدھے ساتھ:\n41۔ اور پادری؛ ایلیاکیم، ماسیہیہ، منیامین، میخایا، ایلیوئنائی، زکریا، {اور} حنانیہ، بگل کے ساتھ؛\n42. اور ماسیہ، اور شمعیہ، اور الیعازر، اور عزی، اور یہوحانان، اور ملکیاہ، اور ایلام، اور ایزر۔ اور گلوکار زور سے گاتے رہے، اور یزریاہ ان کے نگران تھے۔ {گایا...: عبرانی۔ ان کی آواز سنائی دی}\n43۔ اسی دن انہوں نے بڑی قربانیاں دیں اور خوشی منائی: کیونکہ خدا نے انہیں بڑی خوشی سے خوش کیا تھا: بیویاں اور بچے بھی خوش ہوئے، تاکہ یروشلم کی خوشی دور سے بھی سنی جا سکے۔\n44۔ اور اس وقت کچھ لوگ خزانے، نذرانے کے لیے، پہلے پھلوں اور عشر کے لیے کمروں میں مقرر کیے گئے، تاکہ شہروں کے کھیتوں سے شریعت کے حصے کاہنوں اور لاویوں کے لیے جمع کیے جائیں، کیونکہ یہوداہ نے کاہنوں اور انتظار کرنے والوں کے لیے خوشی منائی۔ {قانون کی: یعنی، قانون کے ذریعے مقرر کیا گیا} {یہوداہ کے لیے...: عبرانی۔ یہوداہ کی خوشی کے لیے} {انتظار: عبرانی۔ کھڑا ہوا}\n45۔ اور گلوکار اور دربان دونوں نے اپنے خدا کی حفاظت اور پاکیزگی کی حفاظت کی، جیسا کہ داؤد اور سلیمان اپنے بیٹے کے حکم کے مطابق تھا۔\n46۔ کیونکہ داؤد اور آساف کے زمانے میں قدیم زمانے میں گانے کے سردار اور خدا کے لیے حمد و شکر کے گیت تھے۔\n47۔ اور تمام اسرائیل زروبابل کے زمانے میں، اور نحمیاہ کے زمانے میں، گلوکاروں اور دربانوں کے حصے ہر روز اپنا حصہ دیتے تھے، اور انہوں نے لاویوں کے لیے {مقدس چیزیں} مقدس کر دیں؛ اور لاویوں نے انہیں ہارون کے بچوں کے لیے مقدس قرار دیا۔ {مقدس: یعنی، الگ رکھا گیا}","1۔ اس دن انہوں نے موسیٰ کی کتاب میں لوگوں کے سامعین میں پڑھا؛ اور اس میں لکھا ہوا پایا گیا کہ عمونائٹ اور موآبائی ہمیشہ کے لیے خدا کی جماعت میں نہیں آئیں گے؛ {وہ...: عبرانی۔ وہاں پڑھا گیا} {سامعین: عبرانی۔ کان}\n2۔ کیونکہ انہوں نے بنی اسرائیل سے روٹی اور پانی کے ساتھ ملاقات نہیں کی، بلکہ بلعام کو ان کے خلاف رکھا تاکہ وہ انہیں لعنت دے: لیکن ہمارے خدا نے لعنت کو برکت میں بدل دیا۔\n3۔ اب جب انہوں نے شریعت سن لی تو انہوں نے اسرائیل سے تمام مخلوط ہجوم کو جدا کر دیا۔\n4۔ اور اس سے پہلے، الیاشیب، جو ہمارے خدا کے گھر کے کمرے کی نگرانی کر رہا تھا، توبیاہ کے اتحادی تھا: {تھا...: عبرانی۔ ختم ہو رہا ہے}\n5۔ اور اس نے اس کے لیے ایک بڑا کمرہ تیار کیا تھا، جہاں پہلے گوشت کی قربانیاں، لوبان، برتن، اناج کے عشر، نئی شراب، اور تیل رکھا گیا تھا، جو لاویوں اور گلوکاروں اور قلیوں کو دیا گیا تھا؛ اور پجاریوں کی نذرانے بھی۔ {جو کہ...: عبرانی لاویوں کا حکم}\n6۔ لیکن اس سارے {وقت} میں یروشلم میں نہیں تھا: کیونکہ بابل کے بادشاہ ارتخشیر کے دو اور تیسویں سال میں میں بادشاہ کے پاس آیا، اور کچھ دنوں کے بعد بادشاہ سے اجازت حاصل کی: {بعد...: عبرانی۔ آخر وقت} {حاصل کیا...: یا، میں نے دل سے درخواست کی}\n7۔ اور میں یروشلم آیا، اور اس برائی کو سمجھا جو الیاشیب نے توبیاہ کے لیے کیا، جب اس نے اسے خدا کے گھر کے صحنوں میں ایک کمرہ تیار کیا۔\n8۔ اور اس نے مجھے بہت دکھ دیا: اس لیے میں نے توبیا کے تمام گھریلو سامان کو کمرے سے باہر نکال دیا۔\n9۔ پھر میں نے حکم دیا، اور انہوں نے کمرے صاف کیے، اور وہاں میں خدا کے گھر کے برتن دوبارہ لایا، گوشت کی قربانی اور لوبان کے ساتھ۔\n10۔ اور میں نے محسوس کیا کہ لاویوں کے حصے ابھی تک نہیں دیے گئے تھے: کیونکہ لاویوں اور گلوکاروں کو جو یہ کام کرتے تھے، سب کو اس کے کھیت کی طرف بھاگ گئے۔\n11۔ پھر میں نے حکمرانوں سے بحث کی اور کہا، خدا کا گھر کیوں ترک کیا گیا ہے؟ اور میں نے انہیں اکٹھا کیا، اور ان کی جگہ پر رکھ دیا۔ {جگہ: عبرانی۔ کھڑے ہو جاؤ}\n12۔ پھر تمام یہوداہ کو اناج کا عشر، نئی شراب اور تیل خزانے میں لے آئے۔ {خزانے: یا، گودام}\n13۔ اور میں نے خزانوں کے خزانے دار بنے، شلیمیاہ کو کاہن، اور زادوک کو کاتب بنایا، اور لاویوں کے پیدعیہ کو خزانے دار بنایا: اور ان کے ساتھ حنان تھا جو زکور کا بیٹا تھا، متانیاہ کا بیٹا، کیونکہ وہ وفادار سمجھے جاتے تھے اور ان کا عہدہ ان کے بھائیوں میں تقسیم کرنا تھا۔ {خزانے: یا، گودام} {اگلا...: عبرانی۔ ان کے ہاتھوں سے} {ان کے دفتر...: عبرانی۔ یہ ان پر آ چکا تھا}\n14۔ اے میرے خدا، اس بارے میں مجھے یاد رکھ، اور میرے نیک اعمال کو مٹا نہ دو جو میں نے اپنے خدا کے گھر اور اس کے عہدوں کے لیے کیے ہیں۔ {اچھا...: عبرانی مہربانی} {دفاتر: یا، مشاہدات}\n15۔ ان دنوں میں میں نے یہوداہ میں {کچھ} کو سبت کے دن شراب کے پریس پر چلتے اور گٹھے اور گدھے لاتے دیکھا؛ اسی طرح شراب، انگور، انجیر، اور ہر قسم کے بوجھ جو وہ ہفتہ کے دن یروشلم میں لاتے تھے: اور میں نے ان کے خلاف گواہی دی جب وہ خوراک بیچتے تھے۔\n16۔ وہاں صور کے لوگ بھی رہتے تھے، جو مچھلی اور ہر قسم کا سامان لاتے تھے، اور سبت کے دن یہوداہ کے بچوں اور یروشلم میں فروخت کرتے تھے۔\n17۔ پھر میں نے یہوداہ کے اشرافیہ سے بحث کی اور ان سے کہا، یہ کیا برا کام ہے جو تم کرتے ہو، اور سبت کے دن کی بے حرمتی کرتے ہو؟\n18. کیا تمہارے آباؤ اجداد نے ایسا نہیں کیا، اور کیا ہمارے خدا نے یہ ساری برائی ہم پر اور اس شہر پر نہیں ڈالی؟ پھر بھی تم سبت کی بے حرمتی کر کے اسرائیل پر مزید غصہ لاتے ہو۔\n19۔ اور ایسا ہوا کہ جب یروشلم کے دروازے سبت سے پہلے اندھیرا ہونے لگے، میں نے حکم دیا کہ دروازے بند کیے جائیں، اور حکم دیا کہ انہیں سبت کے بعد تک نہ کھولا جائے: اور {کچھ} میرے خادموں نے مجھے دروازوں پر بٹھا دیا، {تاکہ} سبت کے دن کوئی بوجھ نہ آئے۔\n20۔ تو ہر قسم کے سامان کے تاجر اور بیچنے والے ایک دو بار یروشلم کے بغیر ٹھہرے۔\n21۔ پھر میں نے ان کے خلاف گواہی دی اور کہا، تم دیوار کے پاس کیوں ٹھہرے ہو؟ اگر تم نے دوبارہ ایسا کیا، تو میں تم پر ہاتھ رکھوں گا۔ اس وقت سے وہ سبت کے دن مزید نہیں رہے۔ {بارے میں: عبرانی پہلے}\n22۔ اور میں نے لاویوں کو حکم دیا کہ وہ خود کو پاک کریں، اور وہ آ کر دروازے رکھیں، تاکہ سبت کے دن کو مقدس قرار دیں۔ اے میرے خدا، مجھے یاد رکھ {اس بارے میں} بھی، اور اپنی رحمت کی عظمت کے مطابق مجھے بخش دے۔ {عظمت: یا، کثرت}\n23۔ ان دنوں میں نے یہ بھی دیکھا کہ میں یہودیوں {جو} نے اشدود، آمون، {اور} موآب کی بیویوں سے شادی کی تھی: {تھا...: عبرانی۔ ان کے ساتھ رہنے لگا تھا}\n24۔ اور ان کے بچے آدھی اشدود کی زبان میں بولتے تھے، اور یہودیوں کی زبان میں بول نہیں سکتے تھے، بلکہ ہر قوم کی زبان کے مطابق۔ {ہو سکتا ہے...: عبرانی۔ انہوں نے سمجھا کہ وہ بولنے سے گریز کریں} {ہر ایک کے بارے میں...: عبرانی لوگوں اور لوگوں کی}\n25۔ اور میں نے ان سے بحث کی، انہیں لعنت دی، ان میں سے کچھ کو مارا پیٹا، ان کے بال توڑ دیے، اور خدا کی قسم کھائی کہ تم اپنی بیٹیوں کو ان کے بیٹوں کو نہیں دو گے، نہ ان کی بیٹیوں کو اپنے بیٹوں کے پاس یا اپنے لیے نہیں دو گے۔ {لعنتی: یا، ناپسندیدہ}\n26۔ کیا سلیمان نے اسرائیل کے بادشاہ نے ان باتوں سے گناہ نہیں کیا؟ لیکن بہت سی قوموں میں اس جیسا کوئی بادشاہ نہیں تھا جو اپنے خدا کا محبوب ہو، اور خدا نے اسے پورے اسرائیل کا بادشاہ بنایا؛ پھر بھی اس نے بھی گناہ کرنے والی عورتیں کیں۔\n27۔ تو کیا ہم تمہیں یہ سب بڑی برائی کرنے کی اجازت دیں، ہمارے خدا کی خلاف ورزی کرو اور اجنبی بیویوں سے شادی کرو؟\n28۔ اور یویادا کے بیٹوں میں سے ایک، جو الیاشیب، اعلیٰ کاہن کا بیٹا تھا، سنبلات حورونی کا داماد تھا: اس لیے میں نے اسے اپنے سے نکال دیا۔\n29۔ اے میرے خدا، انہیں یاد رکھ، کیونکہ انہوں نے کاهنت، کاہن کے عہد اور لاویوں کے عہد کو ناپاک کیا ہے۔ {کیونکہ...: عبرانی۔ ناپاک کرنے والوں کے لیے}\n30۔ یوں میں نے انہیں تمام اجنبیوں سے پاک کیا، اور کاہنوں اور لاویوں کی سرپرستی مقرر کی، جو ہر ایک اپنے کام میں تھا؛\n31۔ اور لکڑی کی نذرانہ کے لیے، جو کبھی مقرر کی جاتی ہے، اور پہلے پھلوں کے لیے۔ اے میرے خدا، مجھے ہمیشہ کے لیے یاد رکھنا۔"];
